            />{' '}
            {fromField(`terms-${g}`)}{' '}
          </span>
        ))}
        Late percent: <span data-testid="setting-late-pct-current">{settings?.latePct ?? ''}</span>{' '}
        <input
          data-testid="setting-late-pct"
          onFocus={unchoosePolicy}
          value={latePct}
          placeholder="Late percent (blank: unchanged)"
          onChange={(e) => {
